"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[3222],{3222:e=>{e.exports=JSON.parse('{"slug":"aktivy-nestle-auchan-vremennoe-upravlenie","locale":"ru","title":"\u0410\u043a\u0442\u0438\u0432\u044b Nestle, Auchan, Lemana Pro \u0438 FM Logistic \u043f\u0435\u0440\u0435\u0448\u043b\u0438 \u0432\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \xab\u041b.\u0415.\u0412. \u041c\u0435\u043d\u0435\u0434\u0436\u043c\u0435\u043d\u0442\xbb","description":"\u0423\u043a\u0430\u0437\u043e\u043c \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u0440\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u0438\u0435 \u0430\u043a\u0442\u0438\u0432\u044b Nestle, Auchan, Lemana Pro \u0438 FM Logistic \u043f\u0435\u0440\u0435\u0434\u0430\u043d\u044b \u0432\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \xab\u041b.\u0415.\u0412. \u041c\u0435\u043d\u0435\u0434\u0436\u043c\u0435\u043d\u0442\xbb. \u0423\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0439 \u0443\u0436\u0435 \u043d\u0430\u043f\u0438\u0441\u0430\u043b \xab\u0410\u0448\u0430\u043d\u0443\xbb, \u0447\u0442\u043e \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u044b \u0438 \u0437\u0430\u043a\u0443\u043f\u043a\u0438 \u043d\u0435 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u044f\u0442\u0441\u044f. \u0412\u043b\u0430\u0434\u0435\u043b\u0435\u0446 \u043d\u0430 \u0431\u0443\u043c\u0430\u0433\u0435 \u043e\u0441\u0442\u0430\u043b\u0441\u044f \u043f\u0440\u0435\u0436\u043d\u0438\u043c, \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0443\u0448\u0451\u043b.","blocks":[{"id":"b001","kind":"paragraph","text":"\u0420\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u0438\u0435 \u0430\u043a\u0442\u0438\u0432\u044b \u0447\u0435\u0442\u044b\u0440\u0451\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439 \u043f\u0435\u0440\u0435\u0432\u0435\u0434\u0435\u043d\u044b \u043f\u043e\u0434 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b LEV Management, \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043e\u0444\u043e\u0440\u043c\u043b\u0435\u043d\u043e \u0443\u043a\u0430\u0437\u043e\u043c \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430. \u041f\u043e \xab\u0410\u0448\u0430\u043d\u0443\xbb \u0432\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043f\u0435\u0440\u0435\u0434\u0430\u043d\u044b 100% \u0434\u043e\u043b\u0435\u0439 \u041e\u041e\u041e \xab\u0410\u0448\u0430\u043d\xbb. \u042d\u0442\u043e \u043e\u0447\u0435\u0440\u0435\u0434\u043d\u043e\u0439 \u0448\u0430\u0433 \u0432 \u0434\u043b\u0438\u043d\u043d\u043e\u0439 \u0446\u0435\u043f\u043e\u0447\u043a\u0435 \u043f\u0440\u0438\u043d\u0443\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u043f\u0435\u0440\u0435\u0434\u0430\u0447 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439 \u0438\u0437 \u0441\u0442\u0440\u0430\u043d, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0420\u043e\u0441\u0441\u0438\u044f \u043e\u0442\u043d\u043e\u0441\u0438\u0442 \u043a \u043d\u0435\u0434\u0440\u0443\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c. \u041f\u043e\u0441\u043b\u0435 2022 \u0433\u043e\u0434\u0430 \u0437\u0430\u043f\u0430\u0434\u043d\u044b\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043f\u044b\u0442\u0430\u043b\u0438\u0441\u044c \u043f\u0440\u043e\u0434\u0430\u0442\u044c \u0440\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u0438\u0435 \u043f\u043e\u0434\u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u0438\u043b\u0438 \u0441\u0432\u0435\u0440\u043d\u0443\u0442\u044c \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438, \u043d\u043e \u0441\u0430\u043c\u0430 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u0432\u044b\u0439\u0442\u0438 \u0438\u0437 \u0430\u043a\u0442\u0438\u0432\u0430 \u0441\u0442\u0430\u043b\u0430 \u0437\u0430\u0432\u0438\u0441\u0435\u0442\u044c \u043e\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0432\u043b\u0430\u0441\u0442\u0435\u0439, \u0430 \u043d\u0435 \u043e\u0442 \u0436\u0435\u043b\u0430\u043d\u0438\u044f \u0432\u043b\u0430\u0434\u0435\u043b\u044c\u0446\u0430."},{"id":"b002","kind":"paragraph","text":"\u0423\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u043e\u044f\u0432\u0438\u043b\u0430\u0441\u044c \u0432 \u043a\u043e\u043d\u0446\u0435 2025 \u0433\u043e\u0434\u0430, \u0432\u043e\u0437\u0433\u043b\u0430\u0432\u043b\u044f\u0435\u0442 \u0435\u0451 \u0433\u0435\u043d\u0435\u0440\u0430\u043b \u041c\u0412\u0414, \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e\u0439 \u0438\u0441\u0442\u043e\u0440\u0438\u0438 \u0440\u0430\u0431\u043e\u0442\u044b \u0432 \u0440\u043e\u0437\u043d\u0438\u0446\u0435 \u0438\u043b\u0438 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0435 \u0443 \u043d\u0435\u0451 \u043d\u0435\u0442. \u0413\u0435\u043d\u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440 \xab\u041b.\u0415.\u0412. \u041c\u0435\u043d\u0435\u0434\u0436\u043c\u0435\u043d\u0442\xbb \u0410\u043d\u0434\u0440\u0435\u0439 \u041a\u0440\u0430\u044e\u0448\u043a\u0438\u043d \u043d\u0430\u043f\u0438\u0441\u0430\u043b \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \xab\u0410\u0448\u0430\u043d\u0430\xbb \u043f\u0438\u0441\u044c\u043c\u043e. \u0421\u0435\u0442\u044c \u043e\u0431\u0435\u0449\u0430\u044e\u0442 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0435\u0434\u0438\u043d\u043e\u0439, \u0437\u0430\u043a\u0443\u043f\u043a\u0438, \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0438 \u0440\u0430\u0431\u043e\u0442\u0443 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u043e\u0432 \u043d\u0435 \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u0442\u044c, \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u043f\u0435\u0440\u0435\u0434 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044f\u043c\u0438, \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u0430\u043c\u0438 \u0438 \u0440\u0430\u0431\u043e\u0442\u043d\u0438\u043a\u0430\u043c\u0438 \u0438\u0441\u043f\u043e\u043b\u043d\u044f\u0442\u044c. \u0421\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u0443\u044e \u0440\u0430\u0431\u043e\u0442\u0443 \xab\u0410\u0448\u0430\u043d\u0430\xbb \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0439 \u0441\u0432\u044f\u0437\u0430\u043b \u0441 \u043f\u0440\u043e\u0434\u043e\u0432\u043e\u043b\u044c\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u044c\u044e."},{"id":"b003","kind":"paragraph","text":"\u0412 \u043f\u0438\u0441\u044c\u043c\u0435 \u0435\u0441\u0442\u044c \u0438 \u043c\u0435\u043d\u0435\u0435 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0435 \u043f\u0443\u043d\u043a\u0442\u044b. \u041a\u0440\u0430\u044e\u0448\u043a\u0438\u043d \u043f\u043e\u043e\u0431\u0435\u0449\u0430\u043b \u0437\u0430\u0449\u0438\u0449\u0430\u0442\u044c \u043d\u0435\u0434\u0432\u0438\u0436\u0438\u043c\u043e\u0441\u0442\u044c \u0441\u0435\u0442\u0438 \u043e\u0442 \u0430\u0442\u0430\u043a, \u0432 \u0442\u043e\u043c \u0447\u0438\u0441\u043b\u0435 \u0441 \u043f\u0440\u0438\u043c\u0435\u043d\u0435\u043d\u0438\u0435\u043c \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u043e\u0432, \u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u043d\u044b\u043d\u0435\u0448\u043d\u0435\u0435 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u043e \xab\u0410\u0448\u0430\u043d\u0430\xbb, \u043d\u0435 \u043f\u0435\u0440\u0435\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u044f \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0435\u0433\u043e \u0440\u0430\u0431\u043e\u0442\u044b. \u0421\u0435\u0442\u044c \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u0435 \u043f\u0438\u0441\u044c\u043c\u0430 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u0430, \u0437\u0430\u044f\u0432\u0438\u043b\u0430 \u043e \u0433\u043e\u0442\u043e\u0432\u043d\u043e\u0441\u0442\u0438 \u043a \u0440\u0430\u0431\u043e\u0447\u0435\u043c\u0443 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044e \u0441 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u043c \u0438 \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430, \u0447\u0442\u043e \u0432\u0441\u0435 \u043e\u0431\u044a\u0435\u043a\u0442\u044b \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0442 \u0432 \u0448\u0442\u0430\u0442\u043d\u043e\u043c \u0440\u0435\u0436\u0438\u043c\u0435."},{"id":"b004","kind":"paragraph","text":"\u041c\u0430\u0441\u0448\u0442\u0430\u0431 \u0443 \u0447\u0435\u0442\u044b\u0440\u0451\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 \u0440\u0430\u0437\u043d\u044b\u0439. \u0423 \xab\u0410\u0448\u0430\u043d\u0430\xbb \u0432 \u0420\u043e\u0441\u0441\u0438\u0438 241 \u043c\u0430\u0433\u0430\u0437\u0438\u043d, \u0438\u0437 \u043d\u0438\u0445 62 \u0433\u0438\u043f\u0435\u0440\u043c\u0430\u0440\u043a\u0435\u0442\u0430, \u0438 \u0431\u043e\u043b\u044c\u0448\u0435 33 \u0442\u044b\u0441\u044f\u0447 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a\u043e\u0432. Lemana Pro \u044d\u0442\u043e \u0431\u044b\u0432\u0448\u0438\u0439 Leroy Merlin, \u043e\u043d, \u043a\u0430\u043a \u0438 \xab\u0410\u0448\u0430\u043d\xbb, \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u0441\u0435\u043c\u044c\u0435 \u041c\u044e\u043b\u044c\u0435. \u0420\u043e\u0441\u0441\u0438\u044f \u0434\u0430\u0451\u0442 Nestle \u0447\u0443\u0442\u044c \u0431\u043e\u043b\u044c\u0448\u0435 1% \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u043f\u0440\u043e\u0434\u0430\u0436 \u043f\u0440\u043e\u0442\u0438\u0432 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e 2% \u0434\u043e 2022 \u0433\u043e\u0434\u0430, \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0443\u0436\u0435 \u0441\u0432\u0435\u0440\u043d\u0443\u043b\u0430 \u0431\u043e\u043b\u044c\u0448\u0443\u044e \u0447\u0430\u0441\u0442\u044c \u043f\u0440\u043e\u0434\u0430\u0436, \u0438\u043c\u043f\u043e\u0440\u0442, \u0440\u0435\u043a\u043b\u0430\u043c\u0443 \u0438 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438. \u0423 FM Logistic \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0430\u043a\u0442\u0438\u0432 \u043d\u0435 \u0441\u043a\u043b\u0430\u0434\u044b, \u0430 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u044b, \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u044b \u0438 \u0434\u043e\u0432\u0435\u0440\u0438\u0435 \u043a\u043b\u0438\u0435\u043d\u0442\u043e\u0432, \u0438 \u0435\u0433\u043e \u0443\u043a\u0430\u0437\u043e\u043c \u043f\u0435\u0440\u0435\u0434\u0430\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f."},{"id":"b005","kind":"paragraph","text":"\u041c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 \xab\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0433\u043e \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f\xbb \u043f\u0440\u043e\u0449\u0435, \u0447\u0435\u043c \u0437\u0432\u0443\u0447\u0438\u0442. \u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0443, \u0443 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0432\u043b\u0430\u0434\u0435\u043b\u0435\u0446 \u043e\u0441\u0442\u0430\u043b\u0441\u044f \u043f\u0440\u0435\u0436\u043d\u0438\u043c \u043f\u043e \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u043c, \u043d\u043e \u043a\u043b\u044e\u0447\u0438, \u0434\u043e\u0433\u043e\u0432\u043e\u0440 \u0441 \u0436\u0438\u043b\u044c\u0446\u0430\u043c\u0438 \u0438 \u0430\u0440\u0435\u043d\u0434\u043d\u044b\u0435 \u043f\u043b\u0430\u0442\u0435\u0436\u0438 \u0437\u0430\u0431\u0440\u0430\u043b \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044b\u0439 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0439. \u041f\u0440\u0430\u0432\u043e \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u043d\u0430 \u043c\u0435\u0441\u0442\u0435, \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0438 \u0434\u0435\u043d\u044c\u0433\u0438 \u0443 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430. \u0424\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e \u044d\u0442\u043e \u043e\u0431\u0440\u0430\u0442\u0438\u043c\u043e \u0438 \u043a\u043e\u043d\u0444\u0438\u0441\u043a\u0430\u0446\u0438\u0435\u0439 \u043d\u0435 \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f. \u041d\u0430 \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0435 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a \u0443\u0436\u0435 \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e \u043f\u0440\u043e\u0434\u0430\u0442\u044c \u0430\u043a\u0442\u0438\u0432, \u0432\u044b\u0431\u0440\u0430\u0442\u044c \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044f \u0438 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0446\u0435\u043d\u0443."},{"id":"b006","kind":"paragraph","text":"\u0414\u043b\u044f \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u0435\u0439 \xab\u0410\u0448\u0430\u043d\u0430\xbb \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f, \u044d\u0442\u043e \u0441\u043a\u0430\u0437\u0430\u043b\u0430 \u0441\u0430\u043c\u0430 \u0441\u0435\u0442\u044c. \u0420\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043f\u0438\u0441\u044c\u043c\u0435\u043d\u043d\u043e \u043f\u043e\u043e\u0431\u0435\u0449\u0430\u043b\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c, \u043f\u0435\u0440\u0435\u0434 \u0440\u0430\u0431\u043e\u0442\u043d\u0438\u043a\u0430\u043c\u0438 \u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u0430\u043c\u0438 — \u0438\u0441\u043f\u043e\u043b\u043d\u044f\u0442\u044c \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430. \u041e\u0431\u0435\u0449\u0430\u043d\u0438\u0435 \u043d\u0435 \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u044f, \u043d\u043e \u043e\u043d\u043e \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u043d\u0430 \u0431\u0443\u043c\u0430\u0433\u0435 \u0438 \u0441\u0435\u0442\u044c \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u0430, \u0447\u0442\u043e \u0435\u0433\u043e \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0430. \u0420\u0438\u0441\u043a \u043b\u0435\u0436\u0438\u0442 \u0432 \u0434\u0440\u0443\u0433\u043e\u043c \u043c\u0435\u0441\u0442\u0435: \u0438\u043c\u043f\u043e\u0440\u0442\u043d\u044b\u0435 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 Nestle \u0438 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u044b FM Logistic \u0441 \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u043c\u0438 \u043a\u043b\u0438\u0435\u043d\u0442\u0430\u043c\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043c\u043e\u0433\u0443\u0442 \u043d\u0435 \u0437\u0430\u0445\u043e\u0442\u0435\u0442\u044c \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u0441 \u0430\u043a\u0442\u0438\u0432\u043e\u043c \u0432 \u043d\u043e\u0432\u043e\u043c \u0441\u0442\u0430\u0442\u0443\u0441\u0435. \u041e\u0446\u0435\u043d\u043e\u043a \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430 \u043d\u0435\u0442."},{"id":"b007","kind":"paragraph","text":"\u0427\u0435\u0433\u043e \u043f\u043e\u043a\u0430 \u043d\u0435 \u0437\u043d\u0430\u0435\u043c: \u043f\u043e\u043b\u0443\u0447\u0430\u0442 \u043b\u0438 \u0432\u043b\u0430\u0434\u0435\u043b\u044c\u0446\u044b \u043a\u043e\u043c\u043f\u0435\u043d\u0441\u0430\u0446\u0438\u044e, \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u0441\u044f \u043b\u0438 \u0430\u0441\u0441\u043e\u0440\u0442\u0438\u043c\u0435\u043d\u0442 \u0438 \u0441\u0442\u0430\u043d\u0435\u0442 \u043b\u0438 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0435 \u043f\u043e\u0441\u0442\u043e\u044f\u043d\u043d\u044b\u043c. \u0414\u043b\u044f \u043e\u0431\u044b\u0447\u043d\u043e\u0433\u043e \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430 \u0432\u044b\u0431\u043e\u0440 \u0442\u0430\u043a\u043e\u0439. \u0417\u0430\u043a\u0443\u043f\u0430\u0442\u044c \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u044b \u0432 \xab\u0410\u0448\u0430\u043d\u0435\xbb \u0432\u043f\u0440\u043e\u043a \u0438\u0437-\u0437\u0430 \u043d\u043e\u0432\u043e\u0441\u0442\u0438 \u0437\u043d\u0430\u0447\u0438\u0442 \u043f\u043b\u0430\u0442\u0438\u0442\u044c \u043f\u043e\u043b\u043d\u0443\u044e \u0446\u0435\u043d\u0443 \u0437\u0430 \u0442\u0440\u0435\u0432\u043e\u0433\u0443, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0441\u0435\u0442\u044c \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e \u043e\u043f\u0440\u043e\u0432\u0435\u0440\u0433\u043b\u0430. \u0421\u0447\u0438\u0442\u0430\u0442\u044c, \u0447\u0442\u043e \u0441\u043c\u0435\u043d\u0430 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0435\u0433\u043e \u043d\u0438\u043a\u043e\u0433\u043e \u043d\u0435 \u043a\u0430\u0441\u0430\u0435\u0442\u0441\u044f, \u0442\u043e\u0436\u0435 \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u0441\u044f: \u0434\u043b\u044f 33 \u0442\u044b\u0441\u044f\u0447 \u0447\u0435\u043b\u043e\u0432\u0435\u043a \u044d\u0442\u043e \u0432\u043e\u043f\u0440\u043e\u0441 \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u044b, \u0430 \u0434\u043b\u044f \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044f \u0432\u043e\u043f\u0440\u043e\u0441, \u043a\u0442\u043e \u0438 \u0441 \u043a\u0430\u043a\u043e\u0439 \u043c\u043e\u0442\u0438\u0432\u0430\u0446\u0438\u0435\u0439 \u0442\u0435\u043f\u0435\u0440\u044c \u0440\u0435\u0448\u0430\u0435\u0442, \u0447\u0442\u043e \u043b\u0435\u0436\u0438\u0442 \u043d\u0430 \u043f\u043e\u043b\u043a\u0435."}],"sources":[{"label":"https://www.kommersant.ru/doc/8971025","url":"https://www.kommersant.ru/doc/8971025"},{"label":"https://tass.ru/ekonomika/28132697","url":"https://tass.ru/ekonomika/28132697"},{"label":"https://finance.yahoo.com/economy/policy/articles/russia-seizes-assets-nestle-french-102315087.html","url":"https://finance.yahoo.com/economy/policy/articles/russia-seizes-assets-nestle-french-102315087.html"}],"sourceBodySha256":"cf5b07eda074b3ba8f645b2e30d77d8c2bb3b88d7ecf919b61965f4aca16693c"}')}}]);